<div class="be_page"><div class="be_pagehead be_subhead"><div><div class="muted"><?= e($i['published'] ? t('iss.published_tag') : t('iss.future_tag')) ?></div><h1><?= e(Catalog::issueLabel($i)) ?></h1></div>
<div class="be_headright"><?php if ($i['published']): ?><a class="be_btn" href="<?= e(url('issue', 'view', [$iid])) ?>" target="_blank"><?= e(t('iss.view')) ?></a><form method="post" action="<?= e(url('manageIssues', 'unpublish', [$iid])) ?>" onsubmit="return confirm('<?= e(t('iss.confirm_unpublish')) ?>')"><?= csrf_field() ?><button class="be_btn be_btn_danger" type="submit"><?= e(t('iss.unpublish')) ?></button></form>
<?php else: ?><form class="be_inline" method="post" action="<?= e(url('manageIssues', 'publish', [$iid])) ?>" onsubmit="return confirm('<?= e(t('iss.confirm_publish')) ?>')"><?= csrf_field() ?><label class="be_check"><input type="checkbox" name="notify" value="1"> <?= e(t('iss.notify')) ?></label><button class="be_btn be_btn_primary" type="submit"><?= e(t('iss.publish')) ?></button></form><?php endif; ?></div></div>
<ul class="be_tabs"><li class="active"><a href="<?= e(url('manageIssues', 'edit', [$iid])) ?>"><?= e(t('iss.toc')) ?></a></li><li><a href="<?= e(url('manageIssues', 'form', [$iid])) ?>"><?= e(t('iss.data')) ?></a></li></ul>
