<form class="be_inline" method="post"><?= csrf_field() ?><button class="be_btn be_small" type="submit" formaction="<?= e(url('manageIssues', 'moveSection', [$iid, $secId, 'up'])) ?>"<?= $gi === 1 ? ' disabled' : '' ?>>&uarr;</button><button class="be_btn be_small" type="submit" formaction="<?= e(url('manageIssues', 'moveSection', [$iid, $secId, 'down'])) ?>"<?= $gi === $gn ? ' disabled' : '' ?>>&darr;</button></form></h2>
<table class="be_table"><tbody><?php $n = count($g['rows']); foreach ($g['rows'] as $k => $r): ?><tr><td><a href="<?= e(url('workflow', 'index', [$r['sid'], 5])) ?>"><?= e($r['title']) ?></a><div class="muted be_small"><?= e($r['authors']) ?> &middot; <?= e($r['pages'] ?: '-') ?> &middot; <?= e(t('status.' . $r['sstatus'])) ?></div></td>
<td class="be_actions"><form class="be_inline" method="post"><?= csrf_field() ?><button class="be_btn" type="submit" formaction="<?= e(url('manageIssues', 'moveArticle', [$iid, $r['sid'], 'up'])) ?>"<?= $k === 0 ? ' disabled' : '' ?>>&uarr;</button><button class="be_btn" type="submit" formaction="<?= e(url('manageIssues', 'moveArticle', [$iid, $r['sid'], 'down'])) ?>"<?= $k === $n - 1 ? ' disabled' : '' ?>>&darr;</button>
<button class="be_btn be_btn_danger" type="submit" formaction="<?= e(url('manageIssues', 'removeArticle', [$iid, $r['sid']])) ?>"><?= e(t('iss.remove')) ?></button></form></td></tr><?php endforeach; ?></tbody></table><?php endforeach; ?>
<?php if ($ready): ?><form class="be_upload be_inline_form" method="post" action="<?= e(url('manageIssues', 'addArticle', [$iid])) ?>"><?= csrf_field() ?><select name="submission" aria-label="<?= e(t('iss.add_article')) ?>"><?php foreach ($ready as $r): ?><option value="<?= (int)$r['id'] ?>">#<?= (int)$r['id'] ?> <?= e($r['title']) ?></option><?php endforeach; ?></select><button class="be_btn be_btn_primary" type="submit"><?= e(t('iss.add_article')) ?></button></form><?php endif; ?>
</div></div>
